draw:
var a = p.a, b = p.b;
var mEx = a + b, lEx = a - b, tEx = -2 * a;
var targ = [0, 1, -1];
var got = [mEx, lEx, tEx];
var names = ["M  (mass)", "L  (length)", "T  (time)"];
var pad = 74;
var x0 = pad, x1 = W - 16;
var mid = (x0 + x1) / 2;
var scale = (x1 - x0) / 2 / 2.6;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.lineWidth = 1;

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("v = T_s^a mu^b   ->   M^(a+b) L^(a-b) T^(-2a)", 10, 16);
ctx.fillStyle = C.figure;
ctx.fillText("target for a speed:  M^0 L^1 T^-1", 10, 34);

var ok = true;
for (var i = 0; i < 3; i++) {
  var y = 62 + i * 34;
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x1, y); ctx.stroke();
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(mid, y - 11); ctx.lineTo(mid, y + 11); ctx.stroke();

  ctx.fillStyle = C.ink;
  ctx.textAlign = "right";
  ctx.fillText(names[i], x0 - 8, y);

  var gx = mid + got[i] * scale;
  var tx = mid + targ[i] * scale;
  var hit = Math.abs(got[i] - targ[i]) < 0.01;
  if (!hit) ok = false;

  ctx.strokeStyle = C.accent;
  ctx.lineWidth = hit ? 5 : 3;
  ctx.beginPath(); ctx.moveTo(mid, y); ctx.lineTo(gx, y); ctx.stroke();
  ctx.lineWidth = 1;

  ctx.strokeStyle = C.figure;
  ctx.beginPath();
  ctx.moveTo(tx, y - 13); ctx.lineTo(tx - 5, y - 21); ctx.lineTo(tx + 5, y - 21);
  ctx.closePath(); ctx.stroke();

  ctx.fillStyle = C.figure;
  ctx.textAlign = "center";
  ctx.fillText(targ[i].toFixed(0), tx, y - 28);
  ctx.fillStyle = C.accent;
  ctx.fillText(got[i].toFixed(2), gx, y + 14);
}

if (ok) {
  var pulse = 0.55 + 0.45 * Math.sin(t * 3);
  ctx.globalAlpha = pulse;
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText("all three match:  v = sqrt(T_s / mu)", W / 2, H - 12);
  ctx.globalAlpha = 1;
} else {
  ctx.fillStyle = C.figure;
  ctx.textAlign = "center";
  ctx.fillText("orange bar must reach the outlined marker on every row", W / 2, H - 12);
}

out.note = "a = " + a.toFixed(2) + ", b = " + b.toFixed(2) +
  "   M: " + mEx.toFixed(2) + " (need 0), L: " + lEx.toFixed(2) +
  " (need 1), T: " + tEx.toFixed(2) + " (need -1)" + (ok ? "  SOLVED" : "");

var L = p.L, g = p.g;
var T = 2 * Math.PI * Math.sqrt(L / g);
var th0 = 0.30;
var th = th0 * Math.cos(2 * Math.PI * t / T);

var pad = 20;
var px = W * 0.5;
var py = pad + 8;
var Lmax = 4.2;
var pixPerM = (H - pad * 2 - 26) / Lmax;
var len = L * pixPerM;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.lineWidth = 1;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(px - 46, py); ctx.lineTo(px + 46, py); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + len + 16); ctx.stroke();
ctx.setLineDash([]);

var bx = px + len * Math.sin(th);
var by = py + len * Math.cos(th);

ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 8, 0, Math.PI * 2); ctx.fill();

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(bx, by + 10); ctx.lineTo(bx, by + 10 + g * 1.6); ctx.stroke();
ctx.beginPath();
ctx.moveTo(bx, by + 14 + g * 1.6);
ctx.lineTo(bx - 4, by + 8 + g * 1.6);
ctx.lineTo(bx + 4, by + 8 + g * 1.6);
ctx.closePath(); ctx.fill();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("g", bx + 7, by + 14 + g * 0.8);

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(px - 26, py); ctx.lineTo(px - 26, py + len);
ctx.moveTo(px - 30, py); ctx.lineTo(px - 22, py);
ctx.moveTo(px - 30, py + len); ctx.lineTo(px - 22, py + len);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("L = " + L.toFixed(2) + " m", px - 34, py + len / 2);

var gw = W - 30;
var y0 = H - 14;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(14, y0); ctx.lineTo(14 + gw, y0); ctx.stroke();
var frac = (t % T) / T;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(14, y0); ctx.lineTo(14 + gw * frac, y0); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("one period", 14, y0 - 12);
ctx.textAlign = "right";
ctx.fillText(T.toFixed(2) + " s", 14 + gw, y0 - 12);

out.note = "T = 2*pi*sqrt(L/g) = 2*pi*sqrt(" + L.toFixed(2) + "/" + g.toFixed(1) +
  ") = " + T.toFixed(2) + " s   (quadruple L and T only doubles)";

var rows = [
  ["people", "2.7e6 people"],
  ["divide by 2.5 people per household", "1.1e6 households"],
  ["divide by 20 households per piano", "5.4e4 pianos"],
  ["times 1 tuning per piano per year", "5.4e4 tunings/yr"],
  ["divide by 1000 tunings per tuner per year", "54 tuners"]
];
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.lineWidth = 1;

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("Fermi chain: each link cancels one unit and hands on the next", 12, 16);

var top = 40;
var gap = (H - top - 16) / rows.length;
var boxW = Math.min(200, W * 0.42);
var bx = W - boxW - 12;

for (var i = 0; i < rows.length; i++) {
  var y = top + gap * i;
  ctx.strokeStyle = i === rows.length - 1 ? C.accent : C.rule;
  ctx.lineWidth = i === rows.length - 1 ? 2 : 1;
  ctx.beginPath();
  ctx.rect(bx, y - 12, boxW, 24);
  ctx.stroke();
  ctx.lineWidth = 1;
  ctx.fillStyle = i === rows.length - 1 ? C.accent : C.ink;
  ctx.textAlign = "center";
  ctx.fillText(rows[i][1], bx + boxW / 2, y);

  if (i > 0) {
    ctx.strokeStyle = C.faint;
    ctx.beginPath();
    ctx.moveTo(bx + boxW / 2, y - 12 - gap + 24);
    ctx.lineTo(bx + boxW / 2, y - 16);
    ctx.stroke();
    ctx.fillStyle = C.figure;
    ctx.beginPath();
    ctx.moveTo(bx + boxW / 2, y - 12);
    ctx.lineTo(bx + boxW / 2 - 4, y - 19);
    ctx.lineTo(bx + boxW / 2 + 4, y - 19);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = C.figure;
    ctx.textAlign = "right";
    ctx.fillText(rows[i][0], bx - 12, y - gap / 2);
  }
}
out.note = "";
